using System.Collections.Generic; using UnityEngine; using UnityEngine.InputSystem.EnhancedTouch; using UnityEngine.XR.ARFoundation; using UnityEngine.XR.ARSubsystems;
namespace BiniarosAR { public class ARPlacementController:MonoBehaviour { public ARRaycastManager raycastManager; public ARPlaneManager planeManager; public Camera arCamera; public Transform pergolaRoot; public bool hidePlanesAfterPlacement=true; readonly List<ARRaycastHit> hits=new(); bool placed; float previousTwist;
 void OnEnable(){EnhancedTouchSupport.Enable();} void OnDisable(){if(EnhancedTouchSupport.enabled)EnhancedTouchSupport.Disable();} void Awake(){if(pergolaRoot)pergolaRoot.gameObject.SetActive(false);} void Update(){var ts=Touch.activeTouches; if(ts.Count==1&&ts[0].phase==UnityEngine.InputSystem.TouchPhase.Began)TryPlace(ts[0].screenPosition); else if(ts.Count==2&&placed){var a=ts[0];var b=ts[1];var d=b.screenPosition-a.screenPosition;float ang=Mathf.Atan2(d.y,d.x)*Mathf.Rad2Deg;if(a.phase==UnityEngine.InputSystem.TouchPhase.Began||b.phase==UnityEngine.InputSystem.TouchPhase.Began)previousTwist=ang;else{float delta=Mathf.DeltaAngle(previousTwist,ang);if(pergolaRoot)pergolaRoot.Rotate(Vector3.up,-delta,Space.World);previousTwist=ang;}}}
 void TryPlace(Vector2 p){if(raycastManager==null||pergolaRoot==null){RuntimeARBootstrap.Status="AR placement is not ready";return;} if(raycastManager.Raycast(p,hits,TrackableType.PlaneWithinPolygon)){var pose=hits[0].pose;float yaw=arCamera?arCamera.transform.eulerAngles.y:0f;pergolaRoot.SetPositionAndRotation(pose.position,Quaternion.Euler(0,yaw,0));pergolaRoot.localScale=Vector3.one;pergolaRoot.gameObject.SetActive(true);placed=true;RuntimeARBootstrap.Status="Pergola placed 1:1";}else RuntimeARBootstrap.Status="No floor detected - move phone slowly";}
 public void ResetPlacement(){placed=false;if(pergolaRoot)pergolaRoot.gameObject.SetActive(false);RuntimeARBootstrap.Status="Scan floor and tap to place";} public void Rotate90(){if(pergolaRoot&&pergolaRoot.gameObject.activeSelf){pergolaRoot.Rotate(Vector3.up,90f,Space.World);RuntimeARBootstrap.Status="Rotated 90°";}}
}}
